import openstack
from taf.cloud.openstack.exceptions import OpenstackException
from ipaddress import IPv6Address, ip_address
from six import u


def _is_ip_v6(ip):
    return isinstance(ip_address(ip), IPv6Address)


def connect(controller_ip,
            port=5000,
            version='v3',
            username='admin',
            password='uteadmin',
            os_tenant='admin',
            protocol='https'):
    """Returns openstack connection object"""
    try:
        controller_ip = controller_ip.decode('utf-8', 'ignore')
    except AttributeError:
        pass
    try:
        controller_ip = u(controller_ip)
    except TypeError:
        pass
    controller_ip = controller_ip.replace('[', '').replace(']', '')

    if _is_ip_v6(controller_ip):
        controller_ip = '[{}]'.format(controller_ip)

    url = "{}://{}:{}/{}".format(protocol, controller_ip, port, version)
    auth_args = {
        'auth_url': url,
        'project_name': os_tenant,
        'username': username,
        'password': password,
        'verify': False,
        'user_domain_name': 'Default',
        'project_domain_name': 'Default'
    }
    return openstack.connection.Connection(**auth_args)


def verify_connection(connection):
    if connection is None:
        exc_msg = "You need to call connect method " \
                  "before accessing connection"
        raise OpenstackException(exc_msg)
